package com.example.demo.service.impl.schedule;
import com.example.demo.mapper.schedule.GymScheduleMapper;import com.example.demo.model.schedule.GymSchedule;import com.example.demo.repository.schedule.GymScheduleRepository;import com.example.demo.service.params.request.schedule.CreateGymScheduleRequest;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.time.*;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class GymScheduleServiceImplTest{@Mock GymScheduleRepository repo;@Mock GymScheduleMapper mapper;GymScheduleServiceImpl service;CreateGymScheduleRequest req=new CreateGymScheduleRequest(DayOfWeek.MONDAY,LocalTime.of(8,0),LocalTime.of(22,0));@BeforeEach void setup(){service=new GymScheduleServiceImpl(repo,mapper);}@Test void createRejectsDuplicateDay(){when(repo.existsByDay(DayOfWeek.MONDAY)).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.create(req));}@Test void updateAndDeletePersistChanges(){GymSchedule s=GymSchedule.builder().day(DayOfWeek.TUESDAY).build();when(repo.findById(1)).thenReturn(Optional.of(s));when(repo.save(s)).thenReturn(s);service.update(1,req);assertEquals(DayOfWeek.MONDAY,s.getDay());assertEquals(LocalTime.of(8,0),s.getOpeningTime());service.delete(1);verify(repo).deleteById(1);}}
